    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_xbible_engine_fn_free_artwork(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_xbible_engine_fn_clone_artwork(handle, status)
        }
    }

    
    /**
     * Extracts colors directly targeting the internal image_bytes payload option
     */override fun `extractColors`(`count`: kotlin.UInt): List<AudioEngineRgbaColor> {
            return FfiConverterSequenceTypeAudioEngineRGBAColor.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_xbible_engine_fn_method_artwork_extract_colors(
        it,
        FfiConverterUInt.lower(`count`),_status)
}
    }
    )
    }
    

    override fun `imageBytes`(): kotlin.ByteArray? {
            return FfiConverterOptionalByteArray.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_xbible_engine_fn_method_artwork_image_bytes(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


