sealed class AudioEngineException: kotlin.Exception() {
    
    class ModuleNotFound(
        
        val `path`: kotlin.String
        ) : AudioEngineException() {
        override val message
            get() = "path=${ `path` }"
    }
    
    class IoFailure(
        
        val `errorMessage`: kotlin.String
        ) : AudioEngineException() {
        override val message
            get() = "errorMessage=${ `errorMessage` }"
    }
    
    class SerializationFailure(
        
        val `errorMessage`: kotlin.String
        ) : AudioEngineException() {
        override val message
            get() = "errorMessage=${ `errorMessage` }"
    }
    
    class DecryptionFailure(
        
        val `errorMessage`: kotlin.String
        ) : AudioEngineException() {
        override val message
            get() = "errorMessage=${ `errorMessage` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AudioEngineException> {
        override fun lift(error_buf: RustBuffer.ByValue): AudioEngineException = FfiConverterTypeAudioEngineError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAudioEngineError : FfiConverterRustBuffer<AudioEngineException> {
    override fun read(buf: ByteBuffer): AudioEngineException {
        

        return when(buf.getInt()) {
            1 -> AudioEngineException.ModuleNotFound(
                FfiConverterString.read(buf),
                )
            2 -> AudioEngineException.IoFailure(
                FfiConverterString.read(buf),
                )
            3 -> AudioEngineException.SerializationFailure(
                FfiConverterString.read(buf),
                )
            4 -> AudioEngineException.DecryptionFailure(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AudioEngineException): ULong {
        return when(value) {
            is AudioEngineException.ModuleNotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`path`)
            )
            is AudioEngineException.IoFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
            )
            is AudioEngineException.SerializationFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
            )
            is AudioEngineException.DecryptionFailure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
            )
        }
    }

    override fun write(value: AudioEngineException, buf: ByteBuffer) {
        when(value) {
            is AudioEngineException.ModuleNotFound -> {
                buf.putInt(1)
                FfiConverterString.write(value.`path`, buf)
                Unit
            }
            is AudioEngineException.IoFailure -> {
                buf.putInt(2)
                FfiConverterString.write(value.`errorMessage`, buf)
                Unit
            }
            is AudioEngineException.SerializationFailure -> {
                buf.putInt(3)
                FfiConverterString.write(value.`errorMessage`, buf)
                Unit
            }
            is AudioEngineException.DecryptionFailure -> {
                buf.putInt(4)
                FfiConverterString.write(value.`errorMessage`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



